const seen = new Set<string>();
export const charge = (bookingId: string, cents: number) => {
  if (seen.has(bookingId)) return { cents, status: 'duplicate' };
  seen.add(bookingId);
  return { cents, status: 'charged' };
};

export const signIn = (card: string) => {
  const ok = card.length > 0;
  if (!ok) console.warn('sign-in failed for card ****' + card.slice(-4));
  return ok;
};
